import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long sum = 0, minAbs = Long.MAX_VALUE;
        int negatives = 0;
        for (int i = 0; i < n; i++) {
            long x = nextLong();
            if (x < 0) negatives++;
            long v = Math.abs(x);
            sum += v;
            minAbs = Math.min(minAbs, v);
        }
        // The parity of the number of negatives never changes; an odd count leaves the smallest |x| negative.
        System.out.println(negatives % 2 == 0 ? sum : sum - 2 * minAbs);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	var sum, minAbs int64 = 0, -1
	negatives := 0
	for i := 0; i < n; i++ {
		x := nextInt()
		if x < 0 {
			negatives++
			x = -x
		}
		sum += x
		if minAbs < 0 || x < minAbs {
			minAbs = x
		}
	}
	// The parity of the number of negatives never changes; an odd count leaves the smallest |x| negative.
	if negatives%2 == 1 {
		sum -= 2 * minAbs
	}
